def algorithm(func, dim, lb, ub, budget, rng):
    x_best = np.array([0.5 * (ub + lb)] * dim)
    f_best = func(x_best)

    for _ in range(budget):
        x_cand = np.clip(rng.uniform(size=dim, low=lb, high=ub), a_min=lb, a_max=ub)
        f_cand = func(x_cand)

        if f_cand < f_best:
            x_best = x_cand
            f_best = f_cand

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = None
    best_f = float('inf')

    for _ in range(budget // (dim + 1)):
        x = np.random.uniform(lb, ub, size=dim)

        for t in range(1, budget):
            new_x = x + rng.normal(size=dim) * 0.01
            new_x = np.clip(new_x, lb, ub)

            f_new = func(new_x)
            alpha = 0.9 if f_new < best_f else 1.0

            if f_new < best_f:
                best_f = f_new
                best_x = new_x

            if rng.random() < np.exp((best_f - f_new) / (alpha ** t)):
                x = new_x

    return best_x

